"P-I","dpas":"","serial_number_required":false,"source_file":"Sponsor_FY_MEL_Template_CH_7.30.2026_Costs_Removed.xlsx","source_row":778,"active":true},{"manufacturer":"Belden","manufacturer_part_number":"6543FE 8771000","description":"Spool 9 Conductor Cable GREY CMP (1000')","additional_description":"","category":"Bulk Cable","subcategory":"","budget_unit_price":365,"current_cost":365,"unit_of_measure":"EA","supplier":"","supplier_part_number":"","fsc":"","nsn":"","lead_time":"","purchasable":true,"procurement_status":"P-I","dpas":"","serial_number_required":false,"source_file":"Sponsor_FY_MEL_Template_CH_7.30.2026_Costs_Removed.xlsx","source_row":779,"active":true},{"manufacturer":"C2G","manufacturer_part_number":"43063","description":"250ft RG6/U Quad Shield Coaxial Cable","additional_description":"","category":"Bulk Cable","subcategory":"","budget_unit_price":85,"current_cost":85,"unit_of_measure":"EA","supplier":"","supplier_part_number":"","fsc":"","nsn":"","lead_time":"","purchasable":true,"procurement_status":"P-I","dpas":"","serial_number_required":false,"source_file":"Sponsor_FY_MEL_Template_CH_7.30.2026_Costs_Removed.xlsx","source_row":781,"active":true}]$catalog$::jsonb) as x(
    manufacturer text, manufacturer_part_number text, description text, additional_description text,
    category text, subcategory text, budget_unit_price numeric, current_cost numeric, unit_of_measure text,
    supplier text, supplier_part_number text, fsc text, nsn text, lead_time text, purchasable boolean,
    procurement_status text, dpas text, serial_number_required boolean, source_file text, source_row integer, active boolean
  )
), upserted as (
  insert into public.atlas_products (
    manufacturer, manufacturer_part_number, description, additional_description, category, subcategory,
    budget_unit_price, current_cost, unit_of_measure, supplier, supplier_part_number, fsc, nsn, lead_time,
    purchasable, procurement_status, dpas, serial_number_required, source_file, source_row, active, last_import_batch
  )
  select s.*, (select id from batch) from source_rows s
  on conflict (manufacturer, manufacturer_part_number) do update set
    description = excluded.description, additional_description = excluded.additional_description,
    category = excluded.category, subcategory = excluded.subcategory,
    budget_unit_price = excluded.budget_unit_price, current_cost = excluded.current_cost,
    unit_of_measure = excluded.unit_of_measure, supplier = excluded.supplier,
    supplier_part_number = excluded.supplier_part_number, fsc = excluded.fsc, nsn = excluded.nsn,
    lead_time = excluded.lead_time, purchasable = excluded.purchasable,
    procurement_status = excluded.procurement_status, dpas = excluded.dpas,
    serial_number_required = excluded.serial_number_required, source_file = excluded.source_file,
    source_row = excluded.source_row, active = excluded.active, updated_at = now(), last_import_batch = excluded.last_import_batch
  returning id, current_cost, source_file
), prices as (
  insert into public.atlas_product_pricing_history (product_id, previous_cost, new_cost, import_batch, source_file)
  select u.id, null, u.current_cost, (select id from batch), u.source_file
  from upserted u
  where u.current_cost is not null
    and not exists (select 1 from public.atlas_product_pricing_history h where h.product_id = u.id and h.new_cost = u.current_cost and h.source_file = u.source_file)
  returning product_id
)
insert into public.atlas_catalog_audit_events (product_id, action, import_batch, metadata)
select u.id, 'product.seed_imported', (select id from batch), jsonb_build_object('sourceFile', u.source_file)
from upserted u;

